INSERT IGNORE INTO `cfg_approval_page` (`id`, `template_id`, `view`, `render_mode`, `config`, `route_path`, `version`, `deleted`, `created_at`, `updated_at`) VALUES (9401,9001,'APPROVAL','SECTIONS','{\n  \"renderMode\": \"SECTIONS\",\n  \"width\": \"L\",\n  \"titleTpl\": \"{bizName} · {applicantName}\",\n  \"tipExpr\": \"\",\n  \"sections\": [\n    {\n      \"key\": \"summary\",\n      \"title\": \"基本信息\",\n      \"columns\": 3,\n      \"emphasis\": true,\n      \"fields\": [\n        {\n          \"key\": \"ehr_employee.emp_no\",\n          \"label\": \"工号\",\n          \"source\": \"TABLE\",\n          \"format\": \"text\"\n        },\n        {\n          \"key\": \"ehr_employee.name\",\n          \"label\": \"姓名\",\n          \"source\": \"TABLE\",\n          \"format\": \"text\"\n        },\n        {\n          \"key\": \"ehr_employee.gender\",\n          \"label\": \"性别\",\n          \"source\": \"TABLE\",\n          \"format\": \"text\"\n        },\n        {\n          \"key\": \"ehr_employee.birthday\",\n          \"label\": \"出生日期\",\n          \"source\": \"TABLE\",\n          \"format\": \"date\"\n        },\n        {\n          \"key\": \"ehr_employee.nation\",\n          \"label\": \"民族\",\n          \"source\": \"TABLE\",\n          \"format\": \"text\"\n        },\n        {\n          \"key\": \"ehr_employee.native_place\",\n          \"label\": \"籍贯\",\n          \"source\": \"TABLE\",\n          \"format\": \"text\"\n        },\n        {\n          \"key\": \"ehr_employee.id_card\",\n          \"label\": \"身份证号\",\n          \"source\": \"TABLE\",\n          \"format\": \"text\"\n        },\n        {\n          \"key\": \"ehr_employee.marital_status\",\n          \"label\": \"婚姻状况\",\n          \"source\": \"TABLE\",\n          \"format\": \"text\"\n        },\n        {\n          \"key\": \"ehr_employee.political_status\",\n          \"label\": \"政治面貌\",\n          \"source\": \"TABLE\",\n          \"format\": \"text\"\n        },\n        {